"""Idempotent growth-only public backfill; never rewrites shows or user data."""
import json,zlib,base64
DATA = ''

def apply(c):
 version='growth-backfill-2026-10-21-v1'
 c.execute('CREATE TABLE IF NOT EXISTS public_catalog_patches(version TEXT PRIMARY KEY)')
 if c.execute('SELECT 1 FROM public_catalog_patches WHERE version=?',(version,)).fetchone():return
 from concert_discovery.pastspot import schema
 schema(c);data=json.loads(zlib.decompress(base64.b64decode(DATA)))
 for r in data['history']:
  old=c.execute('SELECT imported_at FROM listener_history WHERE spotify_id=? AND observed_date=?',(r['spotify_id'],r['observed_date'])).fetchone()
  if old and old[0]>=r['imported_at']:continue
  c.execute('INSERT OR REPLACE INTO listener_history VALUES(?,?,?,?,?)',tuple(r[k] for k in ('spotify_id','observed_date','listeners','source_url','imported_at')))
 for r in data['checks']:
  old=c.execute('SELECT checked_at FROM history_checks WHERE spotify_id=?',(r['spotify_id'],)).fetchone()
  if old and old[0]>=r['checked_at']:continue
  c.execute('INSERT OR REPLACE INTO history_checks VALUES(?,?,?)',(r['spotify_id'],r['checked_at'],r['status']))
 c.execute('INSERT INTO public_catalog_patches VALUES(?)',(version,))
